	pub const OP_SNAP_LIST: u16 = 6;
	pub const OP_SNAP_DELETE: u16 = 7;
	pub const OP_SNAP_OPEN: u16 = 8;
	pub const OP_MKDIR: u16 = 9;
	pub const OP_RMDIR: u16 = 10;
