	pub fn list_open<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles) -> Option<(u32, Result<Vec<FileInfo>, Error>)> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let _op = r.u16()?;
		let corr = r.u32()?;
		let path = r.string_lp()?;
		r.finish()?;
		request_handles.clear();
		let items = service.list(path);
		Some((corr, items))
	}
	pub fn list_reply_ok(corr: u32, out: &mut [u8]) -> Option<usize> {
		let mut writer = SliceWriter::new(out);
		let w = &mut writer;
		w.u32(corr)?;
		w.u8(1)?;
		w.u32(0)?;
		Some(writer.pos())
	}
	pub fn list_reply_err(corr: u32, error: &Error, out: &mut [u8]) -> Option<usize> {
		let mut writer = SliceWriter::new(out);
		let w = &mut writer;
		w.u32(corr)?;
		w.u8(0)?;
		error.write(w)?;
		if writer.has_handle() {
			return None;
		}
		Some(writer.pos())
	}
	pub fn list_frame(seq: u32, item: &FileInfo, out: &mut [u8], frame_handles: &mut Handles) -> Option<usize> {
		let mut writer = SliceWriter::new(out);
		let encoded: Option<()> = (|| {
			let w = &mut writer;
			w.u32(seq)?;
			item.write(w)?;
			Some(())
		})();
		if encoded.is_none() {
			if let Some(taken) = Handles::try_from_slice(writer.handles()) {
				*frame_handles = taken;
			}
			return None;
		}
		*frame_handles = Handles::try_from_slice(writer.handles())?;
		Some(writer.pos())
	}
	pub fn list_read(msg: &[u8], frame_handles: &mut Handles) -> Option<FileInfo> {
		let mut reader = Reader::with_handles(msg, frame_handles);
		let r = &mut reader;
		let _seq = r.u32()?;
		let value = FileInfo::read(r)?;
		reader.finish()?;
		frame_handles.clear();
		Some(value)
	}

